trades_actual_price_shape_check.value:
(
        "trades"."actual_entry" IS NULL AND "trades"."actual_initial_stop" IS NULL
      ) OR (
        "trades"."actual_entry" IS NOT NULL AND "trades"."actual_initial_stop" IS NOT NULL
        AND (
          ("trades"."direction" = 'long' AND "trades"."actual_initial_stop" < "trades"."actual_entry")
          OR ("trades"."direction" = 'short' AND "trades"."actual_initial_stop" > "trades"."actual_entry")
        )
      )

trades_planned_price_shape_check.value:
(
        "trades"."planned_entry" IS NULL AND "trades"."planned_stop" IS NULL AND "trades"."planned_target" IS NULL
      ) OR (
        "trades"."planned_entry" IS NOT NULL AND "trades"."planned_stop" IS NOT NULL
        AND (
          (
            "trades"."direction" = 'long'
            AND "trades"."planned_stop" < "trades"."planned_entry"
            AND ("trades"."planned_target" IS NULL OR "trades"."planned_target" > "trades"."planned_entry")
          ) OR (
            "trades"."direction" = 'short'
            AND "trades"."planned_stop" > "trades"."planned_entry"
            AND ("trades"."planned_target" IS NULL OR "trades"."planned_target" < "trades"."planned_entry")
          )
        )
      )
